-- Mailinhalte (fuer Entwuerfe auf Zuruf und Entwurfsangebote) nur 30 Tage aufbewahren; das Mail-Log bleibt.
WITH alt AS (
  DELETE FROM mail_rueckfragen WHERE erstellt_am < now() - interval '30 days' RETURNING id
), verweise AS (
  DELETE FROM ally_gesendete_nachrichten WHERE art = 'mail' AND ref_id IN (SELECT id FROM alt) RETURNING 1
)
SELECT (SELECT count(*) FROM alt) AS mails_geloescht, (SELECT count(*) FROM verweise) AS chat_verweise_geloescht;
